// --- validators --------------------------------------------------------------
//
// Structural rules JSON Schema cannot state per field. Both ends enforce them:
// the server on every vector it receives, every client on every vector the
// server hands back (a malformed vector must never be echoed as base_version).

/// True if `id` is a plausible device identifier: non-empty, at most MAX_DEVICE_ID_LEN characters, and made only of characters a client legitimately emits — ASCII alphanumerics plus `-`, `_`, `:` and `.` (UUIDs, base64url tokens, issuer:label style ids). Rejects control characters and unbounded junk.
pub fn device_id_is_valid(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= MAX_DEVICE_ID_LEN
        && id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b':' | b'.'))
}

/// Validate a version vector's structure before it is compared, stored, or echoed back as base_version. At most MAX_VERSION_ENTRIES entries; every counter at least 1, because a zero counter carries no causal information; every device_id valid and unique, because duplicates make vector-clock comparison ambiguous. The empty vector is well formed: a fresh account has never pushed.
pub fn version_vector_is_well_formed(vector: &VersionVector) -> bool {
    if vector.len() > MAX_VERSION_ENTRIES {
        return false;
    }
    let mut ids = HashSet::with_capacity(vector.len());
    vector.iter().all(|entry| {
        entry.counter >= 1
            && device_id_is_valid(&entry.device_id)
            && ids.insert(entry.device_id.as_str())
    })
}
